// Validate & Rate Limit
const allowedPlatforms = ['instagram', 'linkedin', 'x', 'facebook'];
const allowedTones = ['professional', 'friendly', 'playful', 'bold'];
const now = Date.now();
const HOUR = 3600000;
const DAY = 86400000;

const g = getWorkflowStaticData('global');
if (!g.rate) g.rate = { email: {}, ip: {} };

return items.map(item => {
  const body = item.json.body ?? item.json;
  const headers = item.json.headers ?? {};
  const ip = (headers['x-forwarded-for'] || headers['cf-connecting-ip'] || 'unknown').split(',')[0].trim();

  // Validation
  const errors = [];
  if (!body.email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(body.email)) {
    errors.push('Valid email required');
  }
  if (!body.brand_name || body.brand_name.length < 2) {
    errors.push('Brand name required (min 2 chars)');
  }
  if (!body.industry || body.industry.length < 2) {
    errors.push('Industry required');
  }
  if (!body.tone || !allowedTones.includes(body.tone.toLowerCase())) {
    errors.push('Tone must be: professional, friendly, playful, or bold');
  }
  if (!Array.isArray(body.platforms) || body.platforms.length === 0) {
    errors.push('Select at least one platform');
  } else {
    const invalid = body.platforms.filter(p => !allowedPlatforms.includes(p.toLowerCase()));
    if (invalid.length) errors.push(`Invalid platforms: ${invalid.join(', ')}`);
  }

  // File size check (10MB limit)
  if (body.asset_urls?.some(url => url.size > 10485760)) {
    errors.push('Images must be under 10MB');
  }

  // Rate limiting
  for (const k of Object.keys(g.rate.email)) {
    g.rate.email[k] = (g.rate.email[k] || []).filter(t => (now - t) < HOUR);
  }
  for (const k of Object.keys(g.rate.ip)) {
    g.rate.ip[k] = (g.rate.ip[k] || []).filter(t => (now - t) < DAY);
  }

  const emailKey = body.email?.toLowerCase();
  const emailHits = (g.rate.email[emailKey] || []).length;
  const ipHits = (g.rate.ip[ip] || []).length;

  if (emailHits >= 1) errors.push('Please wait 1 hour between demos');
  if (ip !== 'unknown' && ipHits >= 3) errors.push('Daily demo limit reached (3 per day)');

  if (errors.length) {
    item.json.validation = { ok: false, errors };
  } else {
    // Track rate limit
    g.rate.email[emailKey] = [...(g.rate.email[emailKey] || []), now];
    g.rate.ip[ip] = [...(g.rate.ip[ip] || []), now];

    // Normalize inputs
    item.json.input = {
      brand_name: body.brand_name.trim(),
      industry: body.industry.trim(),
      tone: body.tone.toLowerCase(),
      platforms: body.platforms.map(p => p.toLowerCase()),
      email: emailKey,
      asset_urls: body.asset_urls?.filter(Boolean).slice(0, 2) || [],
      consent: !!body.consent
    };
    item.json.validation = { ok: true };
    item.json.client_ip = ip;
    item.json.request_id = `demo_${now}_${Math.random().toString(36).slice(2, 10)}`;
    item.json.started_at = new Date().toISOString();

    // Initialize timeout tracking
    if (!g.persimmon) g.persimmon = {};
    g.persimmon[item.json.request_id] = {
      startedAt: now,
      responded: false,
      done: false
    };
  }
  return item;
});

