// Build preview HTML for each platform
const previews = [];
const variants = item.json.all_variants || [];

const platforms = {
  instagram: {
    template: (v) => `
      <div class="preview-card instagram">
        <div class="mock-phone">
          <div class="header">@${item.json.input.brand_name}</div>
          <div class="image-placeholder">📸</div>
          <div class="caption">
            <strong>${v.hook}</strong><br>
            ${v.body.substring(0, 125)}...
            <span class="more">more</span>
          </div>
          <div class="hashtags">${v.hashtags.slice(0, 5).map(h => `#${h}`).join(' ')}</div>
        </div>
      </div>`
  },
  linkedin: {
    template: (v) => `
      <div class="preview-card linkedin">
        <div class="post-container">
          <div class="author">${item.json.input.brand_name} • 1st</div>
          <div class="headline">${v.headline}</div>
          <div class="body">${v.body.substring(0, 200)}...</div>
          <div class="hashtags">${v.hashtags.map(h => `#${h}`).join(' ')}</div>
        </div>
      </div>`
  },
  x: {
    template: (v) => `
      <div class="preview-card x-twitter">
        <div class="tweet">
          <div class="author">@${item.json.input.brand_name.toLowerCase().replace(/\s/g, '')}</div>
          <div class="content">${v.tweets[0]}</div>
          ${v.type === 'thread' ? '<div class="thread-indicator">1/3</div>' : ''}
        </div>
      </div>`
  },
  facebook: {
    template: (v) => `
      <div class="preview-card facebook">
        <div class="post">
          <div class="author">${item.json.input.brand_name}</div>
          <div class="content">${v.body.substring(0, 250)}...</div>
          <div class="cta-button">${v.cta}</div>
        </div>
      </div>`
  }
};

// Generate HTML for requested platforms
item.json.input.platforms.forEach(platform => {
  const platformVariants = variants.filter(v => v.platform === platform);
  platformVariants.forEach(variant => {
    if (platforms[platform]) {
      previews.push({
        platform,
        variant: variant.variant,
        html: platforms[platform].template(variant),
        data: variant
      });
    }
  });
});

item.json.previews = previews;
return items;

// Generate unique public token
const token = `demo_${Date.now()}_${Math.random().toString(36).substring(2, 15)}`;

// Prepare database record
item.json.db_record = {
  id: item.json.request_id,
  created_at: new Date().toISOString(),
  email: item.json.input.email,
  brand_name: item.json.input.brand_name,
  industry: item.json.input.industry,
  tone: item.json.input.tone,
  platforms: item.json.input.platforms,
  asset_urls: item.json.input.asset_urls,
  status: 'completed',
  public_token: token,
  generation_time_ms: Date.now() - item.json.started_at,
  previews: item.json.previews
};

item.json.public_url = `${$env.BASE_URL}/demo/${token}`;
return items;

