// Check if already responded via timeout
const g = getWorkflowStaticData('global');
const rid = item.json.request_id;
const state = g.persimmon?.[rid] || {};

if (!state.responded) {
  // Mark as responded
  if (g.persimmon?.[rid]) {
    g.persimmon[rid].responded = true;
    g.persimmon[rid].done = true;
  }

  item.json.should_respond = true;
} else {
  item.json.should_respond = false;
}

return items;

