parameters.functionCode:
// Timeout path - check if main flow completed
const g = getWorkflowStaticData('global');
const rid = item.json.request_id;
const state = g.persimmon?.[rid] || {};

if (!state.responded && !state.done) {
  // Mark as responded
  if (g.persimmon?.[rid]) {
    g.persimmon[rid].responded = true;
  }

  item.json.send_timeout_response = true;
} else {
  item.json.send_timeout_response = false;
}

return items;

